<?php render_grade_breakdown($grade, $book['config']); ?>
<section class="glass panel"><details <?php echo $error ? 'open' : ''; ?>><summary>Adjust / Restore a Grade</summary><form method="post" class="stack-form" data-grade-dirty><?php render_grade_form_fields($book); ?><input type="hidden" name="student_id" value="<?php echo $studentId; ?>"><label><span>Grade to adjust</span><select name="item_id"><option value="overall">Overall grade (0–100)</option><?php foreach ($grade['items'] as $id => $entry): ?><option value="<?php echo esc($id); ?>" <?php echo ($_POST['item_id'] ?? '') === $id ? 'selected' : ''; ?>><?php echo esc($entry['name'] . ' (0–' . $entry['max_score'] . ')'); ?></option><?php endforeach; ?></select></label><label><span>Adjusted value (leave blank when restoring)</span><input name="value" type="number" min="0" max="100000" step="0.01" value="<?php echo esc(is_string($_POST['value'] ?? null) ? $_POST['value'] : ''); ?>"></label><label><span>Note (shared with student when published, optional)</span><textarea name="reason" maxlength="500" rows="2"><?php echo esc(is_string($_POST['reason'] ?? null) ? $_POST['reason'] : ''); ?></textarea></label><div class="action-row"><button class="button button-primary" name="action" value="override">Save Adjustment</button><button class="button button-secondary" name="action" value="restore">Restore Automatic Grade</button></div></form><p>Item adjustments use score units; the overall adjustment uses percentage. The original calculation and change history are preserved.</p></details></section>
<section class="glass panel"><details><summary>Quiz Attempt History</summary><?php $history = array_values(array_filter($attempts, fn($attempt) => (int) $attempt['student_id'] === $studentId)); $historyPage = page_records($history, 'attempt_page', 10); foreach ($historyPage['items'] as $attempt): ?><div class="recent-item"><strong><?php echo esc($attempt['quiz_title']); ?></strong><span><?php echo esc($attempt['score'] . '/' . $attempt['max_score'] . ' · ' . format_date($attempt['played_at'])); ?></span><a class="button button-secondary" href="/QuizWeb/results.php?id=<?php echo (int) $attempt['id']; ?>">View Attempt</a></div><?php endforeach; if (!$history): ?><p>No attempts yet.</p><?php endif; render_pagination($historyPage); ?></details></section>
